// Data dummy untuk simulasi relasi ID -> Nama di Frontend
const mockCustomers = [
  { value: 'CUST-001', label: 'Budi Santoso' },
  { value: 'CUST-002', label: 'Siti Aminah' }
];

const mockKavling = [
  { value: 'KAV-001', label: 'Bumantara - Blok A-01 (Tipe 45/90)' },
  { value: 'KAV-002', label: 'Bumantara - Blok B-12 (Tipe 36/72)' }
];

interface PenjualanData {
  id: string;
  // --- Data Penjualan ---
  customerId: string;
  kavlingId: string;
  totalHargaJual: number; // Sebagai dasar perhitungan tab lain
  diskonPenjualan: number;
  caraPembayaran: string;
  bank: string;
  nilaiPengajuanKpr: number;
  bookingFee: number;
  rekeningTujuan: string;

  // --- Nilai Rumah ---
  nrBiayaKprAsuransi: number; nrDiskonAngsuran: number; nrDiskonCash: number; nrBiayaBbn: number;
  nrBiayaNotarisAjb: number; nrBiayaAppraisal: number; nrBiayaBphtb: number; nrLainLain: number;
  nrTotalSubsidi: number; nrNilaiPenyerahan: number; nrPpn: number; nrBphtb: number; nrPph: number;

  // --- Pajak ---
  pjBiayaKpr: number; pjBiayaAsuransi: number; pjDiskonAngsuran: number; pjBiayaBbn: number;
  pjBiayaAjb: number; pjBiayaAppraisal: number; pjBphtb: number; pjLainLain: number;
  pjTotalSubsidi: number; pjNilaiPenyerahan: number; pjPpn: number; pjBphtbPajak: number;
  pjPph: number; pjTotalBphtbPph: number;

  // --- Keperluan AJB ---
  ajbNjopTanahPerMeter: number; ajbNjopTanah: number; ajbNjopBangunanPerMeter: number;
  ajbNjopBangunan: number; ajbNjopTotal: number; ajbPpn: number; ajbBphtb: number;
  ajbPph: number; ajbTotalBphtbPph: number; ajbSelisihPajakPbb: number; ajbUping: number;
}

const initialFormState: PenjualanData = {
  id: '',
  customerId: '', kavlingId: '', totalHargaJual: 0, diskonPenjualan: 0, caraPembayaran: '', bank: '', nilaiPengajuanKpr: 0, bookingFee: 5000000, rekeningTujuan: '',
  nrBiayaKprAsuransi: 0, nrDiskonAngsuran: 0, nrDiskonCash: 0, nrBiayaBbn: 0, nrBiayaNotarisAjb: 0, nrBiayaAppraisal: 0, nrBiayaBphtb: 0, nrLainLain: 0, nrTotalSubsidi: 0, nrNilaiPenyerahan: 0, nrPpn: 0, nrBphtb: 0, nrPph: 0,
  pjBiayaKpr: 0, pjBiayaAsuransi: 0, pjDiskonAngsuran: 0, pjBiayaBbn: 0, pjBiayaAjb: 0, pjBiayaAppraisal: 0, pjBphtb: 0, pjLainLain: 0, pjTotalSubsidi: 0, pjNilaiPenyerahan: 0, pjPpn: 0, pjBphtbPajak: 0, pjPph: 0, pjTotalBphtbPph: 0,
  ajbNjopTanahPerMeter: 0, ajbNjopTanah: 0, ajbNjopBangunanPerMeter: 0, ajbNjopBangunan: 0, ajbNjopTotal: 0, ajbPpn: 0, ajbBphtb: 0, ajbPph: 0, ajbTotalBphtbPph: 0, ajbSelisihPajakPbb: 0, ajbUping: 0,
};

const SectionTitle = ({ title }: { title: string }) => (

{title}
);

const CustomerKavling = () => {
  const [data, setData] = useState([]);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [formData, setFormData] = useState(initialFormState);
  const [errors, setErrors] = useState<Partial<Record>>({});
  const [isEditing, setIsEditing] = useState(false);
  const [activeTab, setActiveTab] = useState<'transaksi' | 'nilai' | 'pajak' | 'ajb'>('transaksi');

  const getCustomerName = (id: string) => mockCustomers.find(c => c.value === id)?.label || '-';
  const getKavlingInfo = (id: string) => mockKavling.find(k => k.value === id)?.label || '-';

  const columns = [
    { header: 'Nama Customer', accessor: 'customerId', render: (val: string) => getCustomerName(val) },
    { header: 'Kavling', accessor: 'kavlingId', render: (val: string) => getKavlingInfo(val) },
    { header: 'Cara Pembayaran', accessor: 'caraPembayaran' },
    { header: 'Harga Jual', accessor: 'totalHargaJual', render: (val: number) => formatRupiah(val) },
    {
      header: 'Status',
      accessor: 'id',
      render: () => Booked
    },
  ];

  const calculateDerivedFields = (currentData: PenjualanData): PenjualanData => {
    const d = { ...currentData };

    // Auto-kalkulasi Nilai Rumah
    d.nrTotalSubsidi = (Number(d.nrBiayaKprAsuransi) || 0) + (Number(d.nrDiskonAngsuran) || 0) + (Number(d.nrDiskonCash) || 0) + (Number(d.nrBiayaBbn) || 0) + (Number(d.nrBiayaNotarisAjb) || 0) + (Number(d.nrBiayaAppraisal) || 0) + (Number(d.nrBiayaBphtb) || 0) + (Number(d.nrLainLain) || 0);
    d.nrNilaiPenyerahan = (Number(d.totalHargaJual) || 0) - d.nrTotalSubsidi;

    // Auto-kalkulasi Pajak
    d.pjTotalSubsidi = (Number(d.pjBiayaKpr) || 0) + (Number(d.pjBiayaAsuransi) || 0) + (Number(d.pjDiskonAngsuran) || 0) + (Number(d.pjBiayaBbn) || 0) + (Number(d.pjBiayaAjb) || 0) + (Number(d.pjBiayaAppraisal) || 0) + (Number(d.pjBphtb) || 0) + (Number(d.pjLainLain) || 0);
    d.pjNilaiPenyerahan = (Number(d.totalHargaJual) || 0) - d.pjTotalSubsidi;
    d.pjTotalBphtbPph = (Number(d.pjBphtbPajak) || 0) + (Number(d.pjPph) || 0);

    // Auto-kalkulasi AJB
    d.ajbNjopTotal = (Number(d.ajbNjopTanah) || 0) + (Number(d.ajbNjopBangunan) || 0);
    d.ajbTotalBphtbPph = (Number(d.ajbBphtb) || 0) + (Number(d.ajbPph) || 0);

    return d;
  };

  const openModal = (item?: PenjualanData) => {
    if (item) {
      setFormData(item);
      setIsEditing(true);
    } else {
      setFormData(initialFormState);
      setIsEditing(false);
    }
    setErrors({});
    setActiveTab('transaksi');
    setIsModalOpen(true);
  };

  const closeModal = () => {
    setIsModalOpen(false);
    setFormData(initialFormState);
  };

  const handleChange = (e: React.ChangeEvent) => {
    const { name, value, type } = e.target;

    let newData = { ...formData };

    // Auto-reset field KPR jika metode pembayaran diganti
    if (name === 'caraPembayaran' && value !== 'KPR') {
      newData = { ...newData, [name]: value, bank: '', nilaiPengajuanKpr: 0 };
    } else {
      const parsedValue = type === 'number' ? (value === '' ? 0 : Number(value)) : value;
      newData = { ...newData, [name]: parsedValue };
    }

    setFormData(calculateDerivedFields(newData));

    if (errors[name as keyof PenjualanData]) {
      setErrors((prev) => ({ ...prev, [name]: undefined }));
    }
  };

  const validateForm = () => {
    const newErrors: Partial<Record> = {};

    if (!formData.customerId) newErrors.customerId = 'Customer wajib dipilih';
    if (!formData.kavlingId) newErrors.kavlingId = 'Kavling wajib dipilih';
    if (formData.totalHargaJual <= 0) newErrors.totalHargaJual = 'Harga Jual Kesepakatan wajib diisi';
    if (!formData.caraPembayaran) newErrors.caraPembayaran = 'Cara pembayaran wajib dipilih';
    if (!formData.rekeningTujuan) newErrors.rekeningTujuan = 'Rekening transfer wajib dipilih';

    if (formData.caraPembayaran === 'KPR') {
      if (!formData.bank.trim()) newErrors.bank = 'Bank KPR wajib diisi';
      if (formData.nilaiPengajuanKpr <= 0) newErrors.nilaiPengajuanKpr = 'Nilai pengajuan harus lebih dari 0';
    }

    setErrors(newErrors);
    if (Object.keys(newErrors).length > 0) setActiveTab('transaksi');
    return Object.keys(newErrors).length === 0;
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!validateForm()) return;

    if (isEditing) {
      setData((prev) => prev.map((item) => (item.id === formData.id ? formData : item)));
    } else {
      setData((prev) => [...prev, { ...formData, id: Date.now().toString() }]);
    }
    closeModal();
  };

  const handleDelete = (item: PenjualanData) => {
    if (window.confirm(`Hapus data penjualan untuk customer ini?`)) {
      setData((prev) => prev.filter((d) => d.id !== item.id));
    }
  };

  const tabs = [
    { id: 'transaksi', label: 'Data Transaksi' },
    { id: 'nilai', label: 'Nilai Rumah' },
    { id: 'pajak', label: 'Pajak' },
    { id: 'ajb', label: 'Keperluan AJB' },
  ];

  return (


       openModal()}
        onEdit={(item) => openModal(item)}
        onDelete={handleDelete}
      />




          {tabs.map((tab) => (
             setActiveTab(tab.id as any)}
              className={`whitespace-nowrap py-2 px-4 border-b-2 font-medium text-sm transition-colors cursor-pointer ${activeTab === tab.id ? 'border-black text-black' : 'border-transparent text-gray-500 hover:text-gray-700 hover:border-gray-300'
                }`}
            >
              {tab.label}

          ))}




          {/* TAB 1: DATA TRANSAKSI */}
          {activeTab === 'transaksi' && (




















                  {formData.caraPembayaran === 'KPR' && (
                    <>


                    </>
                  )}













          )}

          {/* TAB 2: NILAI RUMAH */}
          {activeTab === 'nilai' && (














                Total Subsidi & Bonus
                - {formatRupiah(formData.nrTotalSubsidi)}



                Nilai Penyerahan (Setelah Subsidi)
                {formatRupiah(formData.nrNilaiPenyerahan)}







          )}

          {/* TAB 3: PAJAK */}
          {activeTab === 'pajak' && (














                Total Subsidi & Bonus (Pajak)
                - {formatRupiah(formData.pjTotalSubsidi)}



                Nilai Penyerahan (Pajak)
                {formatRupiah(formData.pjNilaiPenyerahan)}








                BPHTB + PPh
                {formatRupiah(formData.pjTotalBphtbPph)}


          )}

          {/* TAB 4: KEPERLUAN AJB */}
          {activeTab === 'ajb' && (










                NJOP Tanah + Bangunan
                {formatRupiah(formData.ajbNjopTotal)}









                BPHTB + PPh (AJB)
                {formatRupiah(formData.ajbTotalBphtbPph)}






          )}




              Batal


              Simpan Data Penjualan





  );
};

export default CustomerKavling;

